import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.DZ_cNctr.js";const m=JSON.parse('{"title":"Sample Data and Credits","description":"Where the images in this documentation come from, and how to cite them if you reuse them.","frontmatter":{"title":"Sample Data and Credits","description":"Where the images in this documentation come from, and how to cite them if you reuse them."},"headers":[],"relativePath":"sample-data.md","filePath":"sample-data.md"}'),i={name:"sample-data.md"};function n(l,e,s,d,h,c){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="sample-data-and-credits" tabindex="-1">Sample Data and Credits <a class="header-anchor" href="#sample-data-and-credits" aria-label="Permalink to &quot;Sample Data and Credits&quot;">​</a></h1><p>Every screenshot in these guides uses public data. Nothing here is customer material.</p><p>If you reuse one of these images, cite the source rather than this site.</p><h2 id="whole-slide-h-e-cmu-1" tabindex="-1">Whole-slide H&amp;E, <code>CMU-1</code> <a class="header-anchor" href="#whole-slide-h-e-cmu-1" aria-label="Permalink to &quot;Whole-slide H&amp;E, `CMU-1`&quot;">​</a></h2><p>Used in the <a href="./guides/annotations.html">Annotations</a> and <a href="./guides/templates.html">Annotation Templates</a> guides, and for the brightfield display states in <a href="./guides/channels.html">Channels</a>.</p><p>A freely distributed test slide from the <a href="https://openslide.org/" target="_blank" rel="noreferrer">OpenSlide</a> project, converted to OME-Zarr with <code>bioformats2raw</code>. Widely used for testing whole-slide readers.</p><h2 id="openslide-test-slides" tabindex="-1">OpenSlide test slides <a class="header-anchor" href="#openslide-test-slides" aria-label="Permalink to &quot;OpenSlide test slides&quot;">​</a></h2><p>Used in <a href="./guides/aperio-svs.html">Aperio SVS</a>, <a href="./guides/local-files.html">Local Files</a>, <a href="./guides/authenticated-sources.html">Private Images and Slides</a> and <a href="./guides/sharing.html">Sharing Views</a>: <code>CMU-1.svs</code>, opened as it is, not converted.</p><p>Also in the slide format guides: <code>CMU-2.ndpi</code> (<a href="./guides/hamamatsu-ndpi.html">Hamamatsu NDPI</a>), <code>Leica-2.scn</code> (<a href="./guides/leica-scn.html">Leica SCN</a>), <code>Philips-1.tiff</code> (<a href="./guides/philips-tiff.html">Philips TIFF</a>), <code>CMU-2.mrxs</code> (<a href="./guides/mrxs.html">3DHISTECH MRXS</a>), the DICOM slide <code>Hamamatsu-2</code> (<a href="./guides/dicom-wsi.html">DICOM WSI</a>), and <code>CMU-1.ndpi</code> under an annotation file drawn for <a href="./guides/annotation-exchange.html">Exchanging Annotations</a>.</p><p>From the <a href="https://openslide.cs.cmu.edu/download/openslide-testdata/" target="_blank" rel="noreferrer">OpenSlide test data</a>, CC0, except <code>Leica-2.scn</code>, which OpenSlide lists as free to use and distribute, with or without modification.</p><h2 id="lymph-node-slides-with-tumour-outlines-camelyon16" tabindex="-1">Lymph node slides with tumour outlines, CAMELYON16 <a class="header-anchor" href="#lymph-node-slides-with-tumour-outlines-camelyon16" aria-label="Permalink to &quot;Lymph node slides with tumour outlines, CAMELYON16&quot;">​</a></h2><p>Used in <a href="./guides/annotation-exchange.html">Exchanging Annotations</a>: <code>tumor_001.tif</code> and its ASAP annotation file <code>tumor_001.xml</code>, opened by address, not converted.</p><p>Three slides are also in the viewer&#39;s example gallery, each opening with its pathologist outlines: <code>tumor_001</code>, <code>tumor_044</code> and <code>tumor_076</code>. The viewer reads the slides and their XML files straight from the public bucket. Nothing is re-hosted.</p><p>From the CAMELYON16 challenge, read from <a href="https://registry.opendata.aws/camelyon/" target="_blank" rel="noreferrer">AWS Open Data</a>, <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">CC0</a>. Cite:</p><blockquote><p>Litjens G, Bandi P, Ehteshami Bejnordi B, et al. (2018). 1399 H&amp;E-stained sentinel lymph node sections of breast cancer patients: the CAMELYON dataset. <em>GigaScience</em> 7(6):giy065. <a href="https://doi.org/10.1093/gigascience/giy065" target="_blank" rel="noreferrer">doi:10.1093/gigascience/giy065</a></p></blockquote><blockquote><p>Ehteshami Bejnordi B, et al. (2017). Diagnostic Assessment of Deep Learning Algorithms for Detection of Lymph Node Metastases in Women With Breast Cancer. <em>JAMA</em> 318(22):2199-2210. <a href="https://doi.org/10.1001/jama.2017.14585" target="_blank" rel="noreferrer">doi:10.1001/jama.2017.14585</a></p></blockquote><h2 id="diagnostic-slides-tcga" tabindex="-1">Diagnostic slides, TCGA <a class="header-anchor" href="#diagnostic-slides-tcga" aria-label="Permalink to &quot;Diagnostic slides, TCGA&quot;">​</a></h2><p>Three H&amp;E diagnostic slides in the viewer&#39;s example gallery, one each from lung adenocarcinoma (TCGA-LUAD, case TCGA-49-4514), breast invasive carcinoma (TCGA-BRCA, case TCGA-AO-A1KP) and colon adenocarcinoma (TCGA-COAD, case TCGA-AZ-5407). They are Aperio SVS files, opened as they are from the <a href="https://portal.gdc.cancer.gov/" target="_blank" rel="noreferrer">NCI Genomic Data Commons</a>, open access. Nothing is re-hosted.</p><p>The results shown here are in whole or part based upon data generated by the TCGA Research Network: <a href="https://www.cancer.gov/tcga" target="_blank" rel="noreferrer">https://www.cancer.gov/tcga</a>.</p><blockquote><p>Grossman RL, Heath AP, Ferretti V, et al. (2016). Toward a Shared Vision for Cancer Genomic Data. <em>New England Journal of Medicine</em> 375:1109-1112. <a href="https://doi.org/10.1056/NEJMp1607591" target="_blank" rel="noreferrer">doi:10.1056/NEJMp1607591</a></p></blockquote><h2 id="confocal-czi-bioimage-archive-s-biad4045" tabindex="-1">Confocal CZI, BioImage Archive <code>S-BIAD4045</code> <a class="header-anchor" href="#confocal-czi-bioimage-archive-s-biad4045" aria-label="Permalink to &quot;Confocal CZI, BioImage Archive `S-BIAD4045`&quot;">​</a></h2><p>Used in <a href="./guides/zeiss-czi.html">Zeiss CZI Files</a>: <code>BODIPY2_DFO_rep1.czi</code>, opened as it is. From the <a href="https://www.ebi.ac.uk/biostudies/bioimages/studies/S-BIAD4045" target="_blank" rel="noreferrer">BioImage Archive</a>, study S-BIAD4045, CC0.</p><h2 id="brightfield-ome-tiff-leica-1" tabindex="-1">Brightfield OME-TIFF, <code>Leica-1</code> <a class="header-anchor" href="#brightfield-ome-tiff-leica-1" aria-label="Permalink to &quot;Brightfield OME-TIFF, `Leica-1`&quot;">​</a></h2><p>Used in <a href="./guides/ome-tiff.html">OME-TIFF</a>. Sample OME-TIFF file (c) the OME Consortium, converted with Bio-Formats from a Leica SCN slide in the OpenSlide test data. From <a href="https://downloads.openmicroscopy.org/images/OME-TIFF/2016-06/sub-resolutions/Brightfield/" target="_blank" rel="noreferrer">OME sample data</a>, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p><h2 id="multiplex-qptiff-240508-vet-qctma2-a2-55p-scan1" tabindex="-1">Multiplex QPTIFF, <code>240508_VET_QCTMA2_A2_55p_Scan1</code> <a class="header-anchor" href="#multiplex-qptiff-240508-vet-qctma2-a2-55p-scan1" aria-label="Permalink to &quot;Multiplex QPTIFF, `240508_VET_QCTMA2_A2_55p_Scan1`&quot;">​</a></h2><p>Used in <a href="./guides/akoya-qptiff.html">Akoya QPTIFF</a>. A tissue microarray stained with 59 markers, scanned on an Akoya PhenoCycler-Fusion. By Bryce Fukuda, Jocelyn Wright, Kimberly Smythe and Cecilia Yeung (University of Washington and Fred Hutch Cancer Center), raw example data for the publication &quot;Graphical and Interactive Spatial Proteomics Image Analysis Workflow&quot;. From <a href="https://zenodo.org/records/15825670" target="_blank" rel="noreferrer">Zenodo record 15825670</a>, doi:10.5281/zenodo.15825670, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p><h2 id="high-content-screen-bbbc013" tabindex="-1">High-content screen, <code>BBBC013</code> <a class="header-anchor" href="#high-content-screen-bbbc013" aria-label="Permalink to &quot;High-content screen, `BBBC013`&quot;">​</a></h2><p>Used in <a href="./guides/analytics-phenotyping.html">Analytics &amp; Phenotyping</a>, parts of <a href="./guides/labels.html">Labels</a>, and for the fluorescence display states in <a href="./guides/channels.html">Channels</a>. It is also in the viewer&#39;s example gallery with its masks and measurements, hosted on this site: see <a href="./guides/example-plate-results.html">Example: Plate with Results</a>.</p><p>Human U2OS cells, cytoplasm-to-nucleus translocation, from the <a href="https://bbbc.broadinstitute.org/BBBC013" target="_blank" rel="noreferrer">Broad Bioimage Benchmark Collection</a>. Image set BBBC013v1, provided by Ilya Ravkin, under <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noreferrer">CC BY 3.0</a>.</p><blockquote><p>Ljosa V, Sokolnicki KL, Carpenter AE (2012). Annotated high-throughput microscopy image sets for validation. <em>Nature Methods</em> 9(7):637. <a href="https://doi.org/10.1038/nmeth.2083" target="_blank" rel="noreferrer">doi:10.1038/nmeth.2083</a></p></blockquote><p>The segmentation masks and measurements shown alongside it were produced by running StarDist (nuclei) and Cellpose (cells) over that image set. They are our output, not part of the original collection.</p><h2 id="fluorescence-nuclei-6001240" tabindex="-1">Fluorescence nuclei, <code>6001240</code> <a class="header-anchor" href="#fluorescence-nuclei-6001240" aria-label="Permalink to &quot;Fluorescence nuclei, `6001240`&quot;">​</a></h2><p>Used in <a href="./guides/labels.html">Labels</a>.</p><p>Image 6001240 from the <a href="https://idr.openmicroscopy.org/" target="_blank" rel="noreferrer">Image Data Resource</a>, study <a href="https://idr.openmicroscopy.org/study/idr0062/" target="_blank" rel="noreferrer">idr0062</a>, dataset <code>idr0062-blin-nuclearsegmentation/experimentA</code>. Served from IDR&#39;s public bucket. The viewer&#39;s own <a href="https://find-nuclei.github.io/" target="_blank" rel="noreferrer">live examples</a> read it directly from IDR rather than re-hosting it.</p><blockquote><p>Blin G, Sadurska D, Migueles RP, Chen N, Watson JA, Lowell S (2019). Nessys: A new set of tools for the automated detection of nuclei within intact tissues and dense 3D cultures. <em>PLOS Biology</em> 17(8):e3000388. <a href="https://doi.org/10.1371/journal.pbio.3000388" target="_blank" rel="noreferrer">doi:10.1371/journal.pbio.3000388</a></p></blockquote><p>Published under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Copyright Blin et al.</p><h2 id="plate-76-45" tabindex="-1">Plate, <code>76-45</code> <a class="header-anchor" href="#plate-76-45" aria-label="Permalink to &quot;Plate, `76-45`&quot;">​</a></h2><p>Used in <a href="./guides/hcs-plates.html">OME-Zarr Plates</a> and for the channel controls in <a href="./guides/channels.html">Channels</a>.</p><p>Plate 76-45 from the <a href="https://idr.openmicroscopy.org/" target="_blank" rel="noreferrer">Image Data Resource</a>, study <a href="https://idr.openmicroscopy.org/study/idr0010/" target="_blank" rel="noreferrer">idr0010</a>, screen <code>idr0010-doil-dnadamage/screenA</code>. An RNAi screen for genes whose knockdown changes how 53BP1 accumulates at DNA double-strand breaks. The copy we read was converted to OME-Zarr 0.5 for the <strong>OME 2024 NGFF Challenge</strong>, a community effort to publish a large body of public imaging in the current NGFF version.</p><blockquote><p>Doil C, Mailand N, Bekker-Jensen S, Menard P, Larsen DH, Pepperkok R, Ellenberg J, Panier S, Durocher D, Bartek J, Lukas J, Lukas C (2009). RNF168 binds and amplifies ubiquitin conjugates on damaged chromosomes to allow accumulation of repair proteins. <em>Cell</em> 136(3):435-446. <a href="https://doi.org/10.1016/j.cell.2008.12.041" target="_blank" rel="noreferrer">doi:10.1016/j.cell.2008.12.041</a></p></blockquote><p>Published under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>. Copyright Doil et al.</p><h2 id="opera-phenix-plates-cell-painting-gallery-cpg0000" tabindex="-1">Opera Phenix plates, Cell Painting Gallery <code>cpg0000</code> <a class="header-anchor" href="#opera-phenix-plates-cell-painting-gallery-cpg0000" aria-label="Permalink to &quot;Opera Phenix plates, Cell Painting Gallery `cpg0000`&quot;">​</a></h2><p>Used in <a href="./guides/opera-phenix-plates.html">Opera Phenix Plates</a> and as six of the Cell Painting Gallery plates in the viewer&#39;s example gallery.</p><p>Plates from CPJUMP1, the JUMP Cell Painting pilot, in the <a href="https://registry.opendata.aws/cellpainting-gallery/" target="_blank" rel="noreferrer">Cell Painting Gallery</a> on the Registry of Open Data on AWS. U2OS and A549 cells treated with compounds, CRISPR guides or ORFs, imaged on an Opera Phenix. The viewer reads each plate&#39;s Harmony index and TIFFs straight from the public bucket. Nothing is re-hosted.</p><p>The plates in the example gallery:</p><table tabindex="0"><thead><tr><th>Plate</th><th>Perturbation</th><th>Cells</th></tr></thead><tbody><tr><td>BR00116991</td><td>compounds</td><td>A549</td></tr><tr><td>BR00117011</td><td>compounds</td><td>U2OS</td></tr><tr><td>BR00117004</td><td>CRISPR</td><td>A549</td></tr><tr><td>BR00118045</td><td>CRISPR</td><td>U2OS</td></tr><tr><td>BR00117020</td><td>ORF</td><td>A549</td></tr><tr><td>BR00117022</td><td>ORF</td><td>U2OS</td></tr></tbody></table><blockquote><p>Weisbart E, et al. (2024). Cell Painting Gallery: an open resource for image-based profiling. <em>Nature Methods</em> 21:1775-1777. <a href="https://doi.org/10.1038/s41592-024-02399-z" target="_blank" rel="noreferrer">doi:10.1038/s41592-024-02399-z</a></p></blockquote><blockquote><p>Chandrasekaran SN, et al. (2024). Three million images and morphological profiles of cells treated with matched chemical and genetic perturbations. <em>Nature Methods</em> 21:1114-1121. <a href="https://doi.org/10.1038/s41592-024-02241-6" target="_blank" rel="noreferrer">doi:10.1038/s41592-024-02241-6</a></p></blockquote><p>Published under <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">CC0 1.0</a>. The Cell Painting Gallery asks that you cite the papers above.</p><h2 id="yokogawa-cellvoyager-plates-cell-painting-gallery-cpg0016" tabindex="-1">Yokogawa CellVoyager plates, Cell Painting Gallery <code>cpg0016</code> <a class="header-anchor" href="#yokogawa-cellvoyager-plates-cell-painting-gallery-cpg0016" aria-label="Permalink to &quot;Yokogawa CellVoyager plates, Cell Painting Gallery `cpg0016`&quot;">​</a></h2><p>Used in <a href="./guides/yokogawa-plates.html">Yokogawa CellVoyager Plates</a> and as six of the Cell Painting Gallery plates in the viewer&#39;s example gallery.</p><p>Plates from the JUMP Cell Painting dataset in the <a href="https://registry.opendata.aws/cellpainting-gallery/" target="_blank" rel="noreferrer">Cell Painting Gallery</a>, imaged on a Yokogawa CellVoyager. U2OS cells. The viewer reads each plate&#39;s <code>MeasurementData.mlf</code> and TIFFs straight from the public bucket. Nothing is re-hosted.</p><p>The plates in the example gallery:</p><table tabindex="0"><thead><tr><th>Source</th><th>Plate</th><th>Plate type</th><th>Microscope</th><th>Fields</th><th>Channels</th></tr></thead><tbody><tr><td>source_2</td><td>1053600674</td><td>TARGET2</td><td>CV8000</td><td>6</td><td>6</td></tr><tr><td>source_5</td><td>ACPJUM012</td><td>TARGET2</td><td>CV8000</td><td>9</td><td>6</td></tr><tr><td>source_6</td><td>110000293081</td><td>TARGET2</td><td>CV8000</td><td>9</td><td>6</td></tr><tr><td>source_10</td><td>Dest210726-160150</td><td>TARGET2</td><td>CV8000</td><td>6</td><td>6</td></tr><tr><td>source_13</td><td>CP-CC9-R1-29</td><td>TARGET2</td><td>CV7000</td><td>9</td><td>5</td></tr><tr><td>source_2</td><td>1053601756</td><td>compounds</td><td>CV8000</td><td>6</td><td>6</td></tr></tbody></table><blockquote><p>Chandrasekaran SN, et al. (2023). JUMP Cell Painting dataset: morphological impact of 136,000 chemical and genetic perturbations. <em>bioRxiv</em>. <a href="https://doi.org/10.1101/2023.03.23.534023" target="_blank" rel="noreferrer">doi:10.1101/2023.03.23.534023</a></p></blockquote><p>Published under <a href="https://creativecommons.org/publicdomain/zero/1.0/" target="_blank" rel="noreferrer">CC0 1.0</a>. The Cell Painting Gallery asks that you cite this paper and the Cell Painting Gallery paper above.</p><h2 id="_3d-volumes-ome-zarr-open-scivis" tabindex="-1">3D volumes, OME-Zarr Open SciVis <a class="header-anchor" href="#_3d-volumes-ome-zarr-open-scivis" aria-label="Permalink to &quot;3D volumes, OME-Zarr Open SciVis&quot;">​</a></h2><p>Used as six of the 3D tiles in the viewer&#39;s example gallery and in <a href="./guides/3d-rendering.html">3D Rendering</a>. The viewer reads them straight from the collection&#39;s public bucket on AWS. Nothing is re-hosted.</p><p>The volumes come from the <a href="https://github.com/InsightSoftwareConsortium/OMEZarrOpenSciVisDatasets" target="_blank" rel="noreferrer">OME-Zarr Open SciVis Datasets</a> collection, an OME-Zarr conversion of the <a href="https://github.com/sci-visus/open-scivis-datasets" target="_blank" rel="noreferrer">Open SciVis Datasets</a>:</p><table tabindex="0"><thead><tr><th>Volume</th><th>Courtesy of</th></tr></thead><tbody><tr><td><code>marmoset_neurons</code></td><td>Frederick Federer, Moran Eye Institute, University of Utah</td></tr><tr><td><code>mri_woman</code></td><td>Siemens Medical Systems, Inc., Iselin, NJ, USA</td></tr><tr><td><code>neocortical_layer_1_axons</code></td><td>V De Paola, MRC Clinical Sciences Center, Imperial College London</td></tr><tr><td><code>aneurism</code></td><td>volvis.org and Philips Research, Hamburg, Germany</td></tr><tr><td><code>skull</code></td><td>volvis.org and Siemens Medical Solutions, Forchheim, Germany</td></tr><tr><td><code>carp</code></td><td>Michael Scheuring, Computer Graphics Group, University of Erlangen, Germany</td></tr></tbody></table><blockquote><p>McCormick M. (2025). OME-Zarr Open SciVis Datasets. Zenodo. <a href="https://doi.org/10.5281/zenodo.17495294" target="_blank" rel="noreferrer">doi:10.5281/zenodo.17495294</a></p></blockquote><p>Listed on the Registry of Open Data on AWS under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a> unless a dataset says otherwise; none of these six does.</p><h2 id="zebrafish-lateral-line-idr0079" tabindex="-1">Zebrafish lateral line, <code>idr0079</code> <a class="header-anchor" href="#zebrafish-lateral-line-idr0079" aria-label="Permalink to &quot;Zebrafish lateral line, `idr0079`&quot;">​</a></h2><p>The 3D tile &quot;Lateral Line in 3D&quot; in the example gallery opens series 0 of <code>idr0079_images.zarr</code> from the <a href="https://idr.openmicroscopy.org/" target="_blank" rel="noreferrer">Image Data Resource</a>, study <a href="https://idr.openmicroscopy.org/study/idr0079/" target="_blank" rel="noreferrer">idr0079</a>. Read directly from IDR&#39;s public bucket. Published under <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>; see the study page for the paper (<a href="https://doi.org/10.7554/eLife.55913" target="_blank" rel="noreferrer">doi:10.7554/eLife.55913</a>).</p><h2 id="hipsc-colony-with-nuclei-segmentation-allen-institute-for-cell-science" tabindex="-1">hiPSC colony with nuclei segmentation, Allen Institute for Cell Science <a class="header-anchor" href="#hipsc-colony-with-nuclei-segmentation-allen-institute-for-cell-science" aria-label="Permalink to &quot;hiPSC colony with nuclei segmentation, Allen Institute for Cell Science&quot;">​</a></h2><p>The 3D tile &quot;hiPSC Colony and Segmentation in 3D&quot; in the example gallery opens <code>20200323_06_medium/raw.ome.zarr</code> from the <a href="https://open.quiltdata.com/b/allencell/tree/aics/nuc-morph-dataset/" target="_blank" rel="noreferrer">nuc-morph dataset</a> and loads the nuclei segmentation next to it (<code>seg.ome.zarr</code>, in the same folder) through the link&#39;s <code>labels=</code> parameter. Both are read straight from the Allen Institute&#39;s public bucket; nothing is copied or hosted here. The tile opens with the EGFP channel only, so the first 3D read stays at one channel. Expect it to take around 20 seconds.</p><blockquote><p>Dixon et al. (2025). Cell Systems. <a href="https://doi.org/10.1016/j.cels.2025.101265" target="_blank" rel="noreferrer">doi:10.1016/j.cels.2025.101265</a></p></blockquote><p>Image credit: Allen Institute. The data is under the Allen Institute Terms of Use, which allow research and other noncommercial use.</p><h2 id="synthetic-rgb" tabindex="-1">Synthetic RGB <a class="header-anchor" href="#synthetic-rgb" aria-label="Permalink to &quot;Synthetic RGB&quot;">​</a></h2><p>Used for the RGB control in <a href="./guides/channels.html">Channels</a>.</p><p>Generated by us as a test fixture. Not real microscopy, and not something to cite.</p>',71)])])}const u=t(i,[["render",n]]);export{m as __pageData,u as default};
